effect.shader:
void main(){
    vec2 cell = vec2(size)/acScreenSize;
    vec2 base = (floor(acScreenNorm/cell)+0.5)*cell;
    vec4 col = texture2DCv(inputImg.texture, base);
    if(roundTiles){
        vec2 f = fract(acScreenNorm/cell)-0.5;
        float m = step(length(f), 0.5);
        col *= m;
    }
    gl_FragColor = col;
}
